import {AudioEngine} from './audio-engine.js';
import {createAudioLab} from './lab.js';
import {PROVIDERS,RECOMMENDATIONS,getSuggestions,getProviderSearchUrl,parseServiceLink} from './providers.js';
const api=window.velvet;
const $=(q,root=document)=>root.querySelector(q);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=s=>Number.isFinite(s)&&s>0?`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`:'0:00';
const uuid=()=>crypto.randomUUID();
const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',discover:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5z"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',library:'<path d="M4 4v16M9 4v16M14 5l5-1 3 15-5 1z"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',history:'<path d="M3 11a9 9 0 1 1 2.6 7M3 4v7h7M12 7v5l3 2"/>',lab:'<path d="M4 9v6M8 5v14M12 2v20M16 7v10M20 10v4"/>',palette:'<circle cx="12" cy="12" r="9"/><circle cx="8" cy="9" r="1"/><circle cx="14" cy="7" r="1"/><circle cx="17" cy="12" r="1"/><path d="M7 16c0-2 4-3 5-1s-1 4-3 3"/>',settings:'<path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z"/><path d="m10 3 4 0 1 3 3 1 3 2v5l-3 2-1 3-3 2h-4l-2-3-3-1-2-3v-4l3-2 1-3z"/>',play:'<path d="m8 4 12 8-12 8z" fill="currentColor" stroke="none"/>',pause:'<path d="M7 5h4v14H7zM14 5h4v14h-4z" fill="currentColor" stroke="none"/>',next:'<path d="m5 5 10 7-10 7z" fill="currentColor" stroke="none"/><path d="M19 5v14"/>',previous:'<path d="m19 5-10 7 10 7z" fill="currentColor" stroke="none"/><path d="M5 5v14"/>',shuffle:'<path d="M3 5h3c5 0 7 14 12 14h3m-4-4 4 4-4 3M3 19h3c2 0 4-3 5-6m2-2c2-4 3-6 5-6h3m-4-3 4 3-4 4"/>',repeat:'<path d="M3 10V7a3 3 0 0 1 3-3h14m-4-3 4 3-4 3M21 14v3a3 3 0 0 1-3 3H4m4-3-4 3 4 3"/>',volume:'<path d="M3 9h4l5-4v14l-5-4H3zM16 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',queue:'<path d="M3 5h18M3 10h13M3 15h10M17 14l5 4-5 4z"/>',mini:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M12 12h7v6h-7z"/>',sleep:'<path d="M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11Z"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',folder:'<path d="M3 5h6l2 3h10v12H3z"/>',file:'<path d="M6 3h8l4 4v14H6zM14 3v5h5M9 13h6M9 17h6"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 3H3v18h18v-7"/>',dots:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',link:'<path d="m10 13 4-4M8 15l-2 2a4 4 0 0 1-5-5l5-5a4 4 0 0 1 5 0m2 2 2-2a4 4 0 0 1 5 5l-5 5a4 4 0 0 1-5 0"/>',check:'<path d="m5 12 4 4L20 5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 10-8 10S4 17 4 12V6zM8 12l3 3 5-6"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.play}</svg>`;
const THEMES={velvet:{label:'Velvet',bg:'#101112',surface:'#191a1c',elevated:'#222326',text:'#f5f3f0',muted:'#97979e',accent:'#d4b7ff',border:'#ffffff0e'},daylight:{label:'Daylight',bg:'#f2efeb',surface:'#ffffff',elevated:'#e8e4e0',text:'#24212c',muted:'#696472',accent:'#7652b3',border:'#24212c12'},oled:{label:'OLED',bg:'#000000',surface:'#0c0c0e',elevated:'#171719',text:'#f5f3fa',muted:'#99949f',accent:'#aee9bc',border:'#ffffff14'},dusk:{label:'Rose dusk',bg:'#181317',surface:'#231b21',elevated:'#30242d',text:'#fff1f3',muted:'#b6a0aa',accent:'#f4b1bb',border:'#f4b1bb18'}};
let state={tracks:[],playlists:[],folders:[],favorites:[],queue:[],queueIndex:0,history:[],settings:{},watchedFolders:[]};
let route='discover',backStack=[],activePlaylist=null,query='',mood='all',filters={genre:'all',energy:'all',decade:'all'},catalog=[],catalogStatus='',catalogSequence=0;
let saveTimer,saveChain=Promise.resolve(),toastTimer,activeImport=null,preview=null,undoAction=null,sleepDeadline=0,sleepDuration=0,playedSeconds=0,lastPlaybackTime=0,historyTrack=null,lastRecord=Date.now();
let backgroundVideo=null,selectedTracks=new Set(),dragIndex=null,currentId=null;
const audio=$('#audio'),engine=new AudioEngine(audio);
const lab=createAudioLab({engine,onChange:()=>{state.settings.audio=engine.exportSettings();save();},toast});
const settingsDefaults={theme:'velvet',radius:16,spacing:28,sidebarWidth:215,artworkSize:150,font:'Segoe UI',dim:.68,blur:0,volume:.7,shuffle:false,repeat:'off',historyEnabled:true,historyRetention:90,queueVisible:true,visualizer:true,visualizerStyle:'bars',reducedMotion:false};
function track(id){return state.tracks.find(t=>t.id===id)||RECOMMENDATIONS.find(t=>t.id===id)||catalog.find(t=>t.id===id);}
function current(){return track(currentId||state.queue[state.queueIndex]);}
function localTracks(){return state.tracks.filter(t=>t.source==='local');}
function save(){clearTimeout(saveTimer);saveTimer=setTimeout(flush,220);}
function flush(){clearTimeout(saveTimer);const snapshot=structuredClone(state);saveChain=saveChain.then(()=>api.saveState(snapshot)).catch(e=>toast('Could not save: '+e.message));return saveChain;}
function toast(message,undo){clearTimeout(toastTimer);const el=$('#toast');el.innerHTML=esc(message)+(undo?'<button data-action="undo">Undo</button>':'');undoAction=undo||null;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),undo?7000:4200);}
function cover(t,extra=''){const colors=t?.colors||(['blue-hour','glasshouse','orbit'].map(x=>'demo-'+x).includes(t?.id)?({'demo-blue-hour':['#6f83a2','#272e50'],'demo-glasshouse':['#bdbf92','#506b5e'],'demo-orbit':['#cf8f9d','#5e4b7c']}[t.id]):['#8d789d','#343d59']);return `<div class="cover ${extra}" style="--c1:${esc(colors[0])};--c2:${esc(colors[1])}">${t?.artwork?`<img src="${esc(t.artwork)}" alt="${esc(t.album||t.title)} artwork" loading="lazy">`:`<div class="cover-generated"></div><div class="cover-typography"><span>VELVET SELECTS / ${esc(t?.year||'2026')}</span><strong>${esc(t?.title||'Find your frequency')}</strong><small>${esc(t?.artist||'Your music, your atmosphere')}</small></div>`}</div>`;}
function sourceLabel(t){return t.source==='local'?'LOCAL':t.source==='discovery'?'SUGGESTION':t.source==='catalog'?'CATALOGUE':t.source.toUpperCase();}
function badge(t){return `<span class="source-badge ${t.source==='local'?'local':''}">${sourceLabel(t)}</span>`;}
function liked(id){return state.favorites.includes(id);}
function card(t){return `<article class="music-card">${cover(t)}${badge(t)}<button class="card-play" data-action="play-track" data-id="${esc(t.id)}" aria-label="${t.source==='local'?'Play':'Open listening options for'} ${esc(t.title)}">${icon(t.source==='local'?'play':'external')}</button><h3>${esc(t.title)}</h3><p>${esc(t.artist)}${t.reason?' · '+esc(t.reason.split(' · ')[0]):''}</p></article>`;}
function rows(tracks,{playlist=false,selection=false}={}){if(!tracks.length)return empty('No songs here yet','Add some audio, save a suggestion, or try a different search.','import','Add music');return `<div class="track-list"><div class="track-header"><span>${selection?'✓':'#'}</span><span>TITLE / ARTIST</span><span>ALBUM / SOURCE</span><span>TIME</span><span></span><span></span></div>${tracks.map((t,i)=>`<div class="track-row ${current()?.id===t.id?'current':''}" ${playlist?'draggable="true"':''} data-track-row="${esc(t.id)}" data-index="${i}"><div class="track-index">${selection?`<input type="checkbox" data-select="${esc(t.id)}" aria-label="Select ${esc(t.title)}" ${selectedTracks.has(t.id)?'checked':''}>`:`<button data-action="play-track" data-id="${esc(t.id)}" aria-label="Play ${esc(t.title)}">${current()?.id===t.id&&!audio.paused?icon('lab'):String(i+1).padStart(2,'0')}</button>`}</div><div class="track-info" data-action="play-track" data-id="${esc(t.id)}" tabindex="0" role="button" aria-label="${t.source==='local'?'Play':'Listening options for'} ${esc(t.title)}">${cover(t)}<div><strong>${esc(t.title)}</strong><small>${esc(t.artist)}</small></div></div><div class="track-album">${esc(t.album||sourceLabel(t))}${t.source!=='local'?'<br>'+badge(t):''}</div><span class="track-duration">${t.duration?fmt(t.duration):'↗'}</span><button class="icon-button ${liked(t.id)?'liked':''}" data-action="favorite" data-id="${esc(t.id)}" aria-label="${liked(t.id)?'Unlike':'Like'} ${esc(t.title)}">${icon('heart')}</button><button class="icon-button" data-action="track-menu" data-id="${esc(t.id)}" aria-label="More options for ${esc(t.title)}">${icon('dots')}</button></div>`).join('')}</div>`;}
function empty(title,message,action,label){return `<div class="empty-state"><h3>${esc(title)}</h3><p>${esc(message)}</p>${action?`<button class="button" data-action="${action}">${esc(label)}</button>`:''}</div>`;}
function heading(title,subtitle,buttons=''){return `<div class="page-heading"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${buttons}</div>`;}
function setTheme(){const s=state.settings,t={...(THEMES[s.theme]||THEMES.velvet),...(s.colors||{})};for(const key of ['bg','surface','elevated','text','muted','accent','border'])if(/^#[\da-f]{3,8}$/i.test(t[key]))document.documentElement.style.setProperty('--'+key,t[key]);for(const [k,v] of [['radius',s.radius],['space',s.spacing],['sidebar',s.sidebarWidth],['art-size',s.artworkSize],['blur',s.blur]])document.documentElement.style.setProperty('--'+k,Number(v)+'px');document.documentElement.style.setProperty('--dim',s.dim);document.documentElement.style.setProperty('--font',`"${String(s.font||'Segoe UI').replace(/[^\w -]/g,'')}",sans-serif`);document.body.classList.toggle('light-theme',s.theme==='daylight');document.body.classList.toggle('compact',s.compact===true);document.body.classList.toggle('no-motion',s.reducedMotion===true);document.body.classList.toggle('queue-hidden',!s.queueVisible);document.documentElement.style.setProperty('--accent-text',s.theme==='daylight'?'#ffffff':'#21162f');}
function applyBackground(){const b=state.settings.background,root=$('#background');root.replaceChildren();backgroundVideo=null;if(!b?.url)return;const el=document.createElement(b.type==='video'?'video':'img');el.src=b.url;if(b.type==='video'){el.muted=true;el.loop=true;el.autoplay=true;el.playsInline=true;backgroundVideo=el;el.play().catch(()=>{});}else el.alt='';el.onerror=()=>toast('This background could not be opened. Choose it again in Appearance.');root.append(el);}
function renderNav(){const items=[['discover','Discover','discover'],['library','Your library','library'],['favorites','Liked songs','heart'],['history','Listening history','history'],['lab','Audio lab','lab'],['appearance','Appearance','palette']];$('#navigation').innerHTML=items.map(([r,t,i])=>`<button class="nav-item ${route===r?'active':''}" data-action="navigate" data-route="${r}">${icon(i)}${t}</button>`).join('');$('#playlist-nav').innerHTML=[...state.playlists].sort((a,b)=>String(a.folderId||'').localeCompare(String(b.folderId||''))).map((p,i,all)=>(p.folderId&&(i===0||all[i-1].folderId!==p.folderId)?'<div class="playlist-folder-label">'+esc(state.folders.find(f=>f.id===p.folderId)?.name||'Folder')+'</div>':'')+`<button class="playlist-link ${activePlaylist===p.id?'liked':''}" data-action="open-playlist" data-id="${esc(p.id)}"><span class="playlist-dot">${p.smart?'✧':'♫'}</span><span>${esc(p.name)}</span><small>${playlistTracks(p).length}</small></button>`).join('')||'<small style="padding:10px 13px">A good playlist starts here.</small>';}
function playlistTracks(p){if(p.smart){const rule=p.smart;return state.tracks.filter(t=>(!rule.artist||t.artist.toLowerCase().includes(rule.artist.toLowerCase()))&&(!rule.genre||String(t.genre).toLowerCase().includes(rule.genre.toLowerCase()))&&(!rule.source||t.source===rule.source)&&(!rule.favorites||liked(t.id))&&(!rule.minPlays||state.history.filter(e=>e.trackId===t.id).length>=rule.minPlays));}return (p.trackIds||[]).map(track).filter(Boolean);}
function render(){lab.stopVisualization();renderNav();let html='';if(route==='discover')html=discover();else if(route==='search')html=searchView();else if(route==='lab')html=lab.render();else if(route==='appearance')html=appearance();else if(route==='settings')html=settingsView();else if(route==='services')html=servicesView();else if(route==='history')html=historyView();else if(route==='extensions')html=extensionsView();else if(route==='playlist')html=playlistView();else html=libraryView(route==='favorites');$('#content').innerHTML=html;if(route==='lab')lab.afterRender();wireReorder();renderQueue();updatePlayer();}
function navigate(next,remember=true){if(remember&&next!==route)backStack.push({route,activePlaylist});route=next;selectedTracks.clear();render();$('#content').scrollTop=0;}
function suggestions(extra={}){return getSuggestions({mood,...filters,likedArtists:state.tracks.filter(t=>liked(t.id)).map(t=>t.artist),history:state.settings.historyEnabled?state.history.map(e=>track(e.trackId)).filter(Boolean):[],limit:12,...extra});}
function discover(){const recs=suggestions();return heading('Find your frequency.','A little familiar. A little unexpected. Entirely yours.',`<span class="eyebrow">YOUR DAILY ROTATION</span>`)+`<section class="hero"><div class="hero-text"><div class="eyebrow">LESS NOISE. MORE FEELING.</div><h1>Stay for<br>one more song.</h1><p>Find your next obsession, shape your sound,<br>and make this little corner of music yours.</p><div class="row-actions"><button class="button" data-action="play-mix">${icon('play')} Play Velvet Sessions</button><button class="button secondary" data-action="navigate" data-route="appearance">Make it yours</button></div></div><div class="hero-art" aria-hidden="true"></div><span class="hero-caption">A DIFFERENT KIND OF LISTENING</span></section><div class="section-heading"><h2>What’s the mood?</h2><span class="subtle">Go where the music takes you</span></div><div class="chips">${[['all','For you'],['chill','Slow mornings'],['focus','In the zone'],['upbeat','Good energy'],['dreamy','After hours'],['melancholy','In your feelings']].map(([id,label])=>`<button class="chip ${mood===id?'active':''}" data-action="mood" data-value="${id}">${label}</button>`).join('')}</div><div class="section-heading"><h2>A few you might love</h2><button class="text-button" data-action="discover-more">Explore all ${icon('external')}</button></div><div class="cards">${recs.slice(0,4).map(card).join('')}</div><div class="section-heading"><h2>Your own little soundtrack</h2><button class="text-button" data-action="navigate" data-route="library">Open library →</button></div>${rows(localTracks().slice(0,4))}<p class="subtle" style="font-size:9px">Suggestions are curated song references. Choose a service to listen. Velvet Sessions are original, playable instrumentals included with the app.</p>`;}
function libraryView(favorites=false){let list=favorites?state.tracks.filter(t=>liked(t.id)):state.tracks;const search=state.settings.libraryFilter||'';if(search)list=list.filter(t=>`${t.title} ${t.artist} ${t.album}`.toLowerCase().includes(search.toLowerCase()));if(state.settings.librarySort==='artist')list=[...list].sort((a,b)=>a.artist.localeCompare(b.artist));if(state.settings.librarySort==='title')list=[...list].sort((a,b)=>a.title.localeCompare(b.title));return heading(favorites?'Close to your heart.':'Your collection.',`${list.length} songs · Stored on this computer`, `<button class="button" data-action="import">${icon('plus')} Add music</button>`)+`<div class="panel-header"><input id="library-filter" type="text" placeholder="Filter your library…" value="${esc(search)}" aria-label="Filter library"><div class="row-actions"><button class="button secondary small" data-action="play-all">${icon('play')} Play all</button><select id="library-sort" aria-label="Sort library"><option value="added">Date added</option><option value="title" ${state.settings.librarySort==='title'?'selected':''}>Title</option><option value="artist" ${state.settings.librarySort==='artist'?'selected':''}>Artist</option></select><button class="button secondary small" data-action="selection-playlist" ${selectedTracks.size?'':'disabled'}>Add ${selectedTracks.size||''} to playlist</button></div></div>${rows(list,{selection:true})}`;}
function searchView(){const local=state.tracks.filter(t=>`${t.title} ${t.artist} ${t.album}`.toLowerCase().includes(query.toLowerCase()));const curated=suggestions({query,limit:50,mood:'all',...filters});return heading(query?`Searching for “${query}”`:'A world of music.','Search your library, live song metadata, and curated discoveries.')+`<div class="search-service-row">${['spotify','youtube','soundcloud'].map(p=>`<button data-action="service-search" data-source="${p}"><i class="service-dot" style="background:${PROVIDERS[p].color}"></i> Search ${PROVIDERS[p].name} ${icon('external')}</button>`).join('')}</div><div class="filter-row"><select data-discovery="genre" aria-label="Discovery genre">${['all','electronic','indie','rnb','hip-hop','pop','jazz','rock','ambient','soul'].map(x=>`<option ${filters.genre===x?'selected':''} value="${x}">${x==='all'?'All genres':x.toUpperCase()}</option>`).join('')}</select><select data-discovery="energy" aria-label="Discovery energy">${['all','low','medium','high'].map(x=>`<option ${filters.energy===x?'selected':''} value="${x}">${x==='all'?'All energy':x+' energy'}</option>`).join('')}</select><select data-discovery="decade" aria-label="Discovery decade">${['all','2020s','2010s','2000s','1990s','1980s','1970s','1960s','1950s'].map(x=>`<option ${filters.decade===x?'selected':''} value="${x}">${x==='all'?'All decades':x}</option>`).join('')}</select></div>${local.length?'<div class="section-heading"><h2>In your library</h2></div>'+rows(local):''}<div class="section-heading"><h2>Song catalogue</h2><button class="text-button" data-action="catalog-search">${icon('search')} ${catalogStatus==='Searching…'?'Searching…':'Search live catalogue'}</button></div>${catalogStatus?`<p class="notice" role="status">${esc(catalogStatus)}</p>`:''}${catalog.length?rows(catalog):!catalogStatus?'<p class="subtle">Type a song or artist above, then press Enter to search MusicBrainz. Results contain song information; select a listening service to play.</p>':''}<div class="section-heading" style="margin-top:28px"><h2>${query?'From the curated collection':'Discover something good'}</h2><span class="subtle">${curated.length} suggestions</span></div><div class="cards">${curated.map(card).join('')}</div>`;}
function playlistView(){const p=state.playlists.find(x=>x.id===activePlaylist);if(!p)return empty('Playlist not found','It may have been removed.','new-playlist','Create playlist');let ts=playlistTracks(p);return heading(p.name,p.description||`${ts.length} songs · ${p.smart?'Smart playlist · updates automatically':'Local playlist · drag rows to reorder'}`,`<div class="row-actions"><button class="button" data-action="play-playlist">${icon('play')} Play</button><button class="button secondary" data-action="playlist-menu">${icon('dots')}</button></div>`)+`<div class="panel-header"><button class="text-button" data-action="add-to-playlist">${icon('plus')} Add songs</button><div class="row-actions"><button class="text-button" data-action="playlist-sort" data-value="title">Sort by title</button><button class="text-button" data-action="playlist-sort" data-value="artist">Sort by artist</button></div></div>${rows(ts,{playlist:!p.smart})}`;}
function historyView(){const events=state.history.filter(e=>e.seconds>0),seconds=events.reduce((a,e)=>a+e.seconds,0);const recent=[...events].reverse().map(e=>track(e.trackId)).filter(Boolean).filter((t,i,all)=>all.findIndex(x=>x.id===t.id)===i);const days=Array.from({length:56},(_,i)=>{const date=new Date();date.setDate(date.getDate()-(55-i));const key=date.toISOString().slice(0,10);return {key,count:events.filter(e=>e.at.slice(0,10)===key).length};});return heading('A record of the feeling.','Your listening history is collected on this computer only.')+`<div class="stat-grid"><div class="stat"><small>TIME LISTENING</small><strong>${Math.floor(seconds/60)}<span class="subtle"> min</span></strong><small>From actual playback events</small></div><div class="stat"><small>LISTENING SESSIONS</small><strong>${events.length}</strong><small>Accumulated in 30-second intervals</small></div><div class="stat"><small>SONGS EXPLORED</small><strong>${recent.length}</strong><small>Unique songs in retained history</small></div></div><section class="panel"><h3>The last eight weeks</h3><div class="calendar">${days.map(d=>`<div class="calendar-day ${d.count?'listened':''}" title="${d.key}: ${d.count} listening events"></div>`).join('')}</div><small>Only days with real playback events are coloured.</small></section><div class="section-heading"><h2>Recently in rotation</h2><button class="text-button" data-action="clear-history">Clear history</button></div>${rows(recent)}`;}
function settingRow(label,description,control){return `<label class="settings-row"><span>${label}${description?`<small>${description}</small>`:''}</span>${control}</label>`;}
function rangeSetting(key,min,max,step=1,suffix=''){const v=state.settings[key];return `<span class="right"><output data-output="${key}">${esc(v)}${suffix}</output><input data-setting="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${v}" aria-label="${key}"></span>`;}
function toggleSetting(key){return `<input type="checkbox" data-setting="${key}" ${state.settings[key]?'checked':''}>`;}
function appearance(){const s=state.settings;return heading('A space that feels like you.','Change the atmosphere. Your music will feel right at home.',`<button class="button secondary" data-action="export-settings">${icon('download')} Export your setup</button>`)+`<section class="panel"><h3>Set the mood</h3><p>Start with a palette. Make every little detail your own.</p><div class="theme-grid">${Object.entries(THEMES).map(([id,t])=>`<button class="theme-preview ${s.theme===id?'active':''}" data-action="theme" data-value="${id}" style="background:${t.bg};color:${t.text}"><i style="background:${t.surface};width:70%"></i><i style="background:${t.accent};width:35%"></i><strong>${t.label}</strong></button>`).join('')}</div></section><section class="panel"><div class="panel-header"><div><h3>Your background, your world</h3><p class="subtle">Photos, animated GIFs & looping video · stored locally</p></div><button class="button secondary small" data-action="clear-background">Remove</button></div><div class="background-preview">${s.background? s.background.type==='video'?`<video src="${esc(s.background.url)}" muted autoplay loop playsinline aria-label="Background preview"></video>`:`<img src="${esc(s.background.url)}" alt="Background preview">`:''}<button class="button" data-action="background-upload">${icon('plus')} Upload image, GIF or video</button><span class="background-preview-label">${esc(s.background?.name||'JPG · PNG · WebP · GIF · MP4 · WebM · MOV, up to 200 MB')}</span></div>${settingRow('Dimming','Keep the music in focus.',rangeSetting('dim',0,.96,.01))}${settingRow('Background blur','Add a little softness.',rangeSetting('blur',0,24,1,' px'))}</section><div class="two-col"><section class="panel"><h3>Colour outside the lines</h3>${['bg','surface','elevated','text','muted','accent'].map(key=>settingRow(({bg:'Background',surface:'Panels',elevated:'Controls',text:'Main text',muted:'Secondary text',accent:'Accent & playback'})[key],'',`<input type="color" data-color="${key}" aria-label="${key} colour" value="${esc(s.colors?.[key]||(THEMES[s.theme]||THEMES.velvet)[key])}">`)).join('')}${settingRow('Borders','Colour; subtle transparency is added.',`<input type="color" data-color="border" aria-label="Border colour" value="${esc((s.colors?.border||'#ffffff').slice(0,7))}">`)}</section><section class="panel"><h3>The finishing touches</h3>${settingRow('Corner radius','',rangeSetting('radius',0,30,1,' px'))}${settingRow('Content spacing','',rangeSetting('spacing',16,48,1,' px'))}${settingRow('Sidebar width','',rangeSetting('sidebarWidth',170,300,1,' px'))}${settingRow('Artwork size','Minimum card width.',rangeSetting('artworkSize',120,230,5,' px'))}${settingRow('Font','Use a font installed on this computer.',`<select data-setting="font" aria-label="Font">${['Segoe UI','Arial','Georgia','Verdana','Trebuchet MS','Tahoma','Consolas'].map(f=>`<option value="${f}" ${s.font===f?'selected':''}>${f}</option>`).join('')}</select>`)}${settingRow('Custom font family','Installed font name.',`<input data-setting="customFont" type="text" style="width:145px" value="${esc(s.customFont||'')}" placeholder="e.g. Inter">`)}${settingRow('Compact spacing','Show more of your collection.',toggleSetting('compact'))}${settingRow('Queue panel','Keep your next songs in view.',toggleSetting('queueVisible'))}${settingRow('Reduced motion','Reduce interface transitions.',toggleSetting('reducedMotion'))}</section></div><section class="panel"><div class="panel-header"><h3>Take your space with you</h3><div class="row-actions"><button class="button secondary small" data-action="import-settings">Import setup</button><button class="button secondary small" data-action="reset-appearance">Reset appearance</button></div></div><p>Export includes your theme, layout, audio settings and background reference. Background files stay on this computer and must be uploaded again on another device.</p></section>`;}
function servicesView(){return heading('A home for every source.','Know exactly what each source can do in this release.')+`<div class="provider-grid">${Object.values(PROVIDERS).map(p=>`<section class="provider-card"><header><h3 style="color:${p.color}">${esc(p.name)}</h3><span class="source-badge">${esc(p.status)}</span></header><p>${esc(p.description)}</p><div class="capabilities"><span class="capability">Playback: ${esc(p.playback)}</span><span class="capability">Search: ${esc(p.search)}</span><span class="capability">Effects: ${esc(p.effects)}</span></div><p>${esc(p.requirements)}</p>${p.id!=='local'?`<button class="button secondary small" data-action="service-search" data-source="${p.id}" style="margin-top:14px">Open ${esc(p.name)} ${icon('external')}</button>`:''}</section>`).join('')}</div><p class="notice">Velvet’s interface is free of advertising and tracking. Provider websites control their own ads, availability and subscriptions. External playback is separate from Velvet’s local audio pipeline. Spotify, YouTube Music and SoundCloud streaming, sign-in and playlist expansion are planned.</p>`;}
function settingsView(){const s=state.settings;return heading('The small things matter.','Your preferences, privacy and playback.',`<span class="source-badge">VELVET 1.0.0</span>`)+`<section class="panel"><h3>Listening</h3>${settingRow('Preferred listening service','Used when saving catalogue songs as service search references.',`<select data-setting="preferredProvider"><option value="youtube" ${s.preferredProvider==='youtube'?'selected':''}>YouTube Music</option><option value="spotify" ${s.preferredProvider==='spotify'?'selected':''}>Spotify</option><option value="soundcloud" ${s.preferredProvider==='soundcloud'?'selected':''}>SoundCloud</option></select>`)}${settingRow('Global media shortcuts','Ctrl + Alt + Space / Left / Right. Optional; may conflict with other apps.',toggleSetting('globalShortcuts'))}${settingRow('Listening break reminder','A gentle reminder based on actual playback time.',`<select data-setting="breakMinutes">${[0,30,45,60,90].map(v=>`<option value="${v}" ${Number(s.breakMinutes||0)===v?'selected':''}>${v?v+' minutes':'Off'}</option>`).join('')}</select>`)}${settingRow('Sleep timer','Fade the final 15 seconds, then pause.',`<button class="button secondary small" data-action="sleep">${sleepDeadline?'Timer active':'Set a timer'}</button>`)}<div class="settings-row"><span>Providers<small>View working features and source limitations.</small></span><button class="button secondary small" data-action="navigate" data-route="services">View services →</button></div></section><section class="panel"><h3>Files & folders</h3><div class="settings-row"><span>Watch a music folder<small>New supported files are added automatically. Existing files are never modified.</small></span><button class="button secondary small" data-action="watch-folder">Add folder</button></div>${state.watchedFolders.map(f=>`<div class="settings-row"><span>${esc(f.name)}<small>Watched locally</small></span><button class="text-button" data-action="unwatch" data-id="${esc(f.id)}">Stop watching</button></div>`).join('')}<div class="settings-row"><span>Portable playlists<small>JSON, CSV and M3U/M3U8. Local files must already be in your library.</small></span><button class="button secondary small" data-action="import-playlist">Import playlist</button></div></section><section class="panel"><h3>Your data belongs here</h3>${settingRow('Collect listening history','Stored on this computer. Used to rank suggestions.',toggleSetting('historyEnabled'))}${settingRow('History retention','Older playback events are deleted automatically.',`<select data-setting="historyRetention">${[7,30,90,365].map(d=>`<option value="${d}" ${Number(s.historyRetention)===d?'selected':''}>${d} days</option>`).join('')}</select>`)}<div class="settings-row"><span>Export library & history<small>No account passwords or service tokens are stored.</small></span><button class="button secondary small" data-action="export-library">Export JSON</button></div><div class="settings-row"><span>Delete listening history</span><button class="button danger small" data-action="clear-history">Clear history</button></div></section><section class="panel"><h3>Make it work your way</h3><div class="settings-row"><span>Extensions & visualisers<small>Built-in switches and declarative themes. Executable third-party plugins are planned.</small></span><button class="button secondary small" data-action="navigate" data-route="extensions">Manage</button></div><div class="settings-row"><span>Keyboard shortcuts<small>Space: play/pause · /: search · Ctrl+K: commands · Alt+←/→: previous/next · Ctrl+O: import</small></span><button class="button secondary small" data-action="command">Commands</button></div></section>`;}
function extensionsView(){return heading('A little more you.','Built-in additions with clear permissions.')+`<section class="panel"><h3>Live spectrum</h3>${settingRow('Local audio visualiser','Permission: read frequency data from your local playback. No network access.',toggleSetting('visualizer'))}<p class="subtle">Open Audio Lab to see the real spectrum. Analysis stops when the panel is closed.</p></section><section class="panel"><h3>Theme & setup packages</h3><p>Import a validated JSON theme, layout and audio preset. Review the changes before applying. No downloaded JavaScript runs.</p><button class="button secondary" data-action="import-settings" style="margin-top:16px">Import setup package</button></section><section class="panel"><h3>On the roadmap</h3><p>Sandboxed third-party extensions, authorised lyrics providers and optional Spicetify integration are planned. This release is independent of the Spotify desktop client.</p></section>`;}
function renderQueue(){const now=current();const upcoming=state.queue.map((id,i)=>({t:track(id),i})).filter(x=>x.t&&x.i>state.queueIndex);$('#queue-panel').innerHTML=`<div class="queue-title"><h2>Your queue</h2><button class="icon-button" data-action="toggle-queue" aria-label="Hide queue">${icon('close')}</button></div><div class="eyebrow">NOW IN YOUR WORLD</div><div class="queue-now">${cover(now)}<h3>${esc(now?.title||'A little room for music.')}</h3><p>${esc(now?.artist||'Choose a song to get started')}</p></div><div class="queue-next-title"><span class="eyebrow">UP NEXT <span style="color:var(--text)"> · ${upcoming.length}</span></span><button class="text-button" data-action="save-queue">Save</button></div><div id="queue-items">${upcoming.map(({t,i})=>`<div class="queue-item" draggable="true" data-queue-index="${i}">${cover(t)}<button style="text-align:left;padding:0" data-action="queue-play" data-index="${i}"><strong>${esc(t.title)}</strong><small>${esc(t.artist)}</small></button><button class="icon-button" data-action="queue-remove" data-index="${i}" aria-label="Remove ${esc(t.title)} from queue">${icon('close')}</button></div>`).join('')||'<p class="queue-empty">Make room for a favourite.<br>Add songs with “Play next” or play a playlist.</p>'}</div><div class="queue-bottom">${icon('shield')} Your queue is saved automatically.</div><button class="text-button" data-action="clear-queue">Clear upcoming</button>`;wireQueueReorder();}
function updatePlayer(){const t=current();$('#now-playing').innerHTML=`${cover(t)}<div><strong>${esc(t?.title||'Your music, your atmosphere.')}</strong><small>${esc(t?.artist||'Choose something you love')}</small></div>${t?`<button class="icon-button ${liked(t.id)?'liked':''}" data-action="favorite" data-id="${esc(t.id)}" aria-label="Like current song">${icon('heart')}</button>`:''}`;$('#play-main').innerHTML=icon(audio.paused?'play':'pause');$('#play-main').setAttribute('aria-label',audio.paused?'Play':'Pause');$('#shuffle').classList.toggle('active',state.settings.shuffle);$('#repeat').classList.toggle('active',state.settings.repeat!=='off');$('#repeat').title='Repeat: '+state.settings.repeat;$('#repeat').setAttribute('aria-label','Repeat: '+state.settings.repeat);$('#volume').value=Math.round(state.settings.volume*100);$('#volume-icon').classList.toggle('active',audio.muted);$('#duration').textContent=fmt(audio.duration||t?.duration);}
function recordHistory(){if(playedSeconds>.1&&historyTrack&&state.settings.historyEnabled){state.history.push({trackId:historyTrack,at:new Date().toISOString(),seconds:Math.round(playedSeconds*10)/10});const cut=Date.now()-Number(state.settings.historyRetention||90)*86400000;state.history=state.history.filter(e=>Date.parse(e.at)>cut);save();}playedSeconds=0;lastPlaybackTime=audio.currentTime;lastRecord=Date.now();}
async function playTrack(id,queue=null){const t=track(id);if(!t)return;if(t.source!=='local'){listeningOptions(t);return;}recordHistory();if(queue){state.queue=queue.filter(x=>track(x)?.source==='local');state.queueIndex=Math.max(0,state.queue.indexOf(id));}else if(!state.queue.includes(id)){state.queue.push(id);state.queueIndex=state.queue.length-1;}else if(state.queue[state.queueIndex]!==id)state.queueIndex=state.queue.indexOf(id);currentId=id;historyTrack=id;audio.src=t.mediaUrl;audio.playbackRate=engine.settings.speed;await engine.init();audio.volume=state.settings.volume;try{await audio.play();}catch(e){toast('This file could not play: '+e.message);return;}save();updatePlayer();renderQueue();if('mediaSession'in navigator){navigator.mediaSession.metadata=new MediaMetadata({title:t.title,artist:t.artist,album:t.album});}if(route==='library'||route==='favorites'||route==='playlist')render();}
async function togglePlay(){if(!audio.src){const t=current()?.source==='local'?current():localTracks()[0];if(t)await playTrack(t.id);else toast('Import an audio file to start listening.');return;}await engine.init();if(audio.paused)await audio.play();else audio.pause();updatePlayer();}
async function nextTrack(direction=1){recordHistory();if(!state.queue.length)return;if(direction<0&&audio.currentTime>3){audio.currentTime=0;return;}let index=state.queueIndex+direction;if(state.settings.shuffle&&direction>0&&state.queue.length>1){do{index=Math.floor(Math.random()*state.queue.length);}while(index===state.queueIndex);}if(index>=state.queue.length){if(state.settings.repeat==='all')index=0;else{audio.pause();updatePlayer();return;}}if(index<0)index=state.queue.length-1;state.queueIndex=index;await playTrack(state.queue[index]);}
function ensureSaved(t){let existing=state.tracks.find(x=>x.id===t.id);if(existing)return existing;const source=state.settings.preferredProvider||'youtube';existing={id:t.id,title:t.title,artist:t.artist,album:t.album||'',genre:t.genre||'',year:t.year||null,source,externalUrl:t.externalUrl||t.url||getProviderSearchUrl(source,`${t.artist} ${t.title}`),duration:t.duration||0,addedAt:new Date().toISOString()};state.tracks.push(existing);return existing;}
function toggleFavorite(id){const t=track(id);if(!t)return;ensureSaved(t);state.favorites=liked(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();render();}
async function searchCatalog(){if(query.trim().length<2){catalogStatus='Enter at least two characters to search the live catalogue.';if(route==='search')render();return;}const seq=++catalogSequence;catalogStatus='Searching…';catalog=[];if(route==='search')render();try{const results=await api.searchCatalog(query);if(seq!==catalogSequence)return;catalog=results;catalogStatus=results.length?`${results.length} live metadata results from MusicBrainz. Choose a service to listen.`:'No catalogue matches. Try the artist name or search directly in a service.';}catch(e){if(seq!==catalogSequence)return;catalogStatus='Catalogue search is unavailable: '+e.message+' You can still search the provider websites above.';}if(route==='search')render();}
function modal(title,body,footer=''){const dialog=$('#modal');$('#modal-body').innerHTML=`<div class="modal-heading"><h2>${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>${body}${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!dialog.open)dialog.showModal();const first=dialog.querySelector('input:not([type=checkbox]),select');if(first)setTimeout(()=>first.focus(),50);}
function closeModal(){$('#modal').close();if(activeImport){api.cancelImport(activeImport).catch(()=>{});activeImport=null;}}
function listeningOptions(t){modal(t.title,`<p class="modal-body-text">${esc(t.artist)}${t.album?' · '+esc(t.album):''}</p><p class="notice">${t.source==='local'?'This local recording can play in Velvet.':'Choose a service to find this recording. Check the artist and version before playing; Velvet will not automatically substitute a recording.'}</p><div class="command-list">${['spotify','youtube','soundcloud'].map(s=>`<button data-action="listen-service" data-id="${esc(t.id)}" data-source="${s}"><span>${PROVIDERS[s].name}</span>${icon('external')}</button>`).join('')}</div>`,`<button class="button secondary" data-action="save-reference" data-id="${esc(t.id)}">Save to library</button>`);}
function importDialog(){modal('Bring your music.',`<div class="import-options"><button class="import-option" data-action="import-files">${icon('file')}<strong>Choose audio files</strong><small>MP3, FLAC, WAV, M4A, OGG and more</small></button><button class="import-option" data-action="import-folder">${icon('folder')}<strong>A whole folder</strong><small>Include audio in subfolders</small></button></div><label class="modal-field">Or save a service link<input type="url" id="service-link" placeholder="Paste a Spotify, YouTube or SoundCloud link"></label><p class="modal-body-text">Service links save references. Audio is not downloaded, and service playlists are not expanded.</p>`,`<button class="text-button" data-action="import-playlist">Import a playlist file</button><button class="button" data-action="preview-link">Review link →</button>`);}
async function importPaths(paths){if(!paths?.length)return;const token=uuid();activeImport=token;modal('Finding your music…','<p class="modal-body-text" id="import-progress">Reading tags, finding duplicates and preparing a preview.</p>',`<button class="button secondary" data-action="cancel-import">Cancel</button>`);const result=await api.previewImport(paths,token);if(activeImport!==token)return;preview=result;activeImport=result.token;modal('A first look.',`<p class="modal-body-text">${result.tracks.length} new songs · ${result.duplicates.length} duplicates · ${result.unavailable.length} unavailable</p><div class="preview-list">${result.tracks.slice(0,100).map(t=>`<div class="preview-item"><span>${esc(t.title)}<small>${esc(t.artist)}</small></span><span class="source-badge local">NEW</span></div>`).join('')}${result.duplicates.slice(0,8).map(t=>`<div class="preview-item"><span>${esc(t.fileName||t.title||'Duplicate')}</span><small>Already in library</small></div>`).join('')}${result.unavailable.slice(0,8).map(t=>`<div class="preview-item"><span>${esc(t.fileName||t.path||'Unavailable file')}<small>${esc(t.reason||t.error||'Unsupported file')}</small></span></div>`).join('')}</div><p class="modal-body-text">Files stay in their current location. Moving them later may require reimporting them.</p>`,`<button class="button secondary" data-action="cancel-import">Cancel</button><button class="button" data-action="commit-import" ${result.tracks.length?'':'disabled'}>Import ${result.tracks.length} songs</button>`);}
async function commitImport(){if(!activeImport)return;const token=activeImport;activeImport=null;await flush();const result=await api.commitImport(token);state={...result.state,settings:{...settingsDefaults,...result.state.settings}};closeModal();save();navigate('library');toast(`Imported ${result.imported} songs · skipped ${result.duplicates} duplicates · ${result.unavailable} unavailable.`);}
function newPlaylist(ids=[],smart=false){modal(smart?'A playlist that grows with you.':'A new little collection.',`<label class="modal-field">Playlist name<input type="text" id="playlist-name" placeholder="e.g. Long way home" maxlength="120"></label><label class="modal-field">Description<textarea id="playlist-description" rows="2" maxlength="3000" placeholder="A feeling, a place, a time of day…"></textarea></label>${smart?'<label class="modal-field">Artist contains<input id="smart-artist" placeholder="Any artist"></label><label class="modal-field">Genre contains<input id="smart-genre" placeholder="Any genre"></label><label class="modal-field"><input type="checkbox" id="smart-favorites"> Liked songs only</label><label class="modal-field">Minimum actual listening events<input id="smart-plays" type="number" min="0" max="10000" value="0"></label>':''}`,`<button class="button secondary" data-action="close-modal">Cancel</button><button class="button" id="create-playlist-button">Create playlist</button>`);$('#create-playlist-button').onclick=()=>{const name=$('#playlist-name').value.trim();if(!name){$('#playlist-name').focus();return;}const p={id:uuid(),name,description:$('#playlist-description').value,trackIds:[...ids],createdAt:new Date().toISOString(),smart:smart?{artist:$('#smart-artist').value,genre:$('#smart-genre').value,favorites:$('#smart-favorites').checked,minPlays:Number($('#smart-plays').value)}:null};state.playlists.push(p);save();activePlaylist=p.id;closeModal();navigate('playlist');toast('Playlist created. Saved on this computer.');};}
function trackMenu(t){const p=state.playlists.find(p=>p.id===activePlaylist);modal(t.title,`<p class="modal-body-text">${esc(t.artist)} · ${esc(t.album||sourceLabel(t))}</p><div class="command-list" style="margin-top:17px">${t.source==='local'?`<button data-action="play-next" data-id="${esc(t.id)}">Play next ${icon('queue')}</button><button data-action="show-file" data-id="${esc(t.id)}">Show in folder ${icon('folder')}</button>`:`<button data-action="play-track" data-id="${esc(t.id)}">Listening options ${icon('external')}</button>`}<button data-action="choose-playlist" data-id="${esc(t.id)}">Add to a playlist ${icon('plus')}</button><button data-action="edit-track" data-id="${esc(t.id)}">Edit library metadata</button>${p&&!p.smart?`<button data-action="remove-from-playlist" data-id="${esc(t.id)}">Remove from this playlist</button>`:''}<button data-action="remove-track" data-id="${esc(t.id)}">Remove from library</button></div>`);}
function choosePlaylist(ids){ids.forEach(id=>ensureSaved(track(id)));modal('Add to a collection.',`<div class="command-list">${state.playlists.filter(p=>!p.smart).map(p=>`<button data-target-playlist="${esc(p.id)}">${esc(p.name)}<span>${p.trackIds.length} songs</span></button>`).join('')}</div>`,`<button class="button" id="new-from-selection">Create new playlist</button>`);$$('[data-target-playlist]').forEach(b=>b.onclick=()=>{const p=state.playlists.find(x=>x.id===b.dataset.targetPlaylist);p.trackIds=[...new Set([...p.trackIds,...ids])];save();closeModal();render();toast('Added to '+p.name);});$('#new-from-selection').onclick=()=>newPlaylist(ids);}
const $$=(q,root=document)=>[...root.querySelectorAll(q)];
async function dispatch(action,b){const id=b?.dataset.id,t=id?track(id):null;switch(action){
case 'navigate':closeModal();navigate(b.dataset.route);break;
case 'back':{const prev=backStack.pop();if(prev){activePlaylist=prev.activePlaylist;navigate(prev.route,false);}break;}
case 'discover-more':query='';$('#global-search').value='';navigate('search');break;
case 'mood':mood=b.dataset.value;render();break;
case 'play-mix':{const ids=localTracks().map(t=>t.id);if(ids.length)await playTrack(ids[0],ids);break;}
case 'play-track':if(t){if(t.source==='local')closeModal();await playTrack(id);}break;
case 'toggle-play':await togglePlay();break;
case 'next':await nextTrack(1);break;
case 'previous':await nextTrack(-1);break;
case 'play-all':{const ids=(route==='favorites'?state.tracks.filter(t=>liked(t.id)):state.tracks).filter(t=>t.source==='local').map(t=>t.id);if(ids.length)await playTrack(ids[0],ids);else toast('No playable local songs in this collection.');break;}
case 'shuffle':state.settings.shuffle=!state.settings.shuffle;save();updatePlayer();toast(state.settings.shuffle?'Shuffle on':'Shuffle off');break;
case 'repeat':state.settings.repeat=({off:'all',all:'one',one:'off'})[state.settings.repeat]||'off';save();updatePlayer();toast('Repeat '+state.settings.repeat);break;
case 'mute':audio.muted=!audio.muted;updatePlayer();break;
case 'favorite':toggleFavorite(id);break;
case 'toggle-queue':state.settings.queueVisible=!state.settings.queueVisible;setTheme();save();break;
case 'mini':await api.setMiniMode(!document.body.classList.contains('mini-mode'));break;
case 'queue-play':state.queueIndex=Number(b.dataset.index);await playTrack(state.queue[state.queueIndex]);break;
case 'queue-remove':{const i=Number(b.dataset.index),removed=state.queue.splice(i,1)[0];save();renderQueue();toast('Removed from queue.',()=>{state.queue.splice(i,0,removed);save();renderQueue();});break;}
case 'clear-queue':{const old=[...state.queue],i=state.queueIndex;state.queue=state.queue.slice(0,state.queueIndex+1);save();renderQueue();toast('Upcoming queue cleared.',()=>{state.queue=old;state.queueIndex=i;save();renderQueue();});break;}
case 'save-queue':newPlaylist([...state.queue]);break;
case 'play-next':if(t?.source==='local'){state.queue.splice(state.queueIndex+1,0,id);save();closeModal();renderQueue();toast('Playing next: '+t.title);}break;
case 'new-playlist':newPlaylist();break;
case 'selection-playlist':choosePlaylist([...selectedTracks]);break;
case 'open-playlist':activePlaylist=id;navigate('playlist');break;
case 'play-playlist':{const p=state.playlists.find(p=>p.id===activePlaylist),ids=playlistTracks(p).filter(t=>t.source==='local').map(t=>t.id);if(ids.length)await playTrack(ids[0],ids);else toast('This playlist has no local songs. Open service references individually to listen.');break;}
case 'playlist-menu':playlistMenu();break;
case 'playlist-sort':{const p=state.playlists.find(p=>p.id===activePlaylist);if(p.smart){toast('Smart playlists update automatically.');break;}p.trackIds.sort((a,c)=>String(track(a)?.[b.dataset.value]).localeCompare(String(track(c)?.[b.dataset.value])));save();render();break;}
case 'playlist-rename':{const p=state.playlists.find(p=>p.id===activePlaylist);modal('Rename this feeling.',`<label class="modal-field">Name<input id="rename-playlist" value="${esc(p.name)}" maxlength="120"></label><label class="modal-field">Description<textarea id="rename-description">${esc(p.description)}</textarea></label>`,`<button class="button" id="apply-rename">Save</button>`);$('#apply-rename').onclick=()=>{p.name=$('#rename-playlist').value.trim()||p.name;p.description=$('#rename-description').value;save();closeModal();render();};break;}
case 'playlist-duplicate':{const p=state.playlists.find(p=>p.id===activePlaylist);state.playlists.push({...structuredClone(p),id:uuid(),name:p.name+' · copy',createdAt:new Date().toISOString()});save();closeModal();render();toast('Playlist duplicated.');break;}
case 'playlist-delete':{const p=state.playlists.find(p=>p.id===activePlaylist),i=state.playlists.indexOf(p);state.playlists.splice(i,1);save();closeModal();navigate('library');toast('Playlist deleted.',()=>{state.playlists.splice(i,0,p);save();render();});break;}
case 'playlist-export':{const p=state.playlists.find(x=>x.id===activePlaylist);if(p.smart)p.trackIds=playlistTracks(p).map(t=>t.id);await flush();await api.exportPlaylist(activePlaylist,b.dataset.format||'json');closeModal();break;}
case 'smart-playlist':newPlaylist([],true);break;
case 'add-to-playlist':{const p=state.playlists.find(x=>x.id===activePlaylist);if(p.smart){toast('This playlist uses rules. Add matching tracks to your library.');break;}modal('Pick a few favourites.',`<div class="preview-list">${state.tracks.map(t=>`<label class="preview-item"><span>${esc(t.title)}<small>${esc(t.artist)}</small></span><input type="checkbox" data-playlist-add="${esc(t.id)}" ${p.trackIds.includes(t.id)?'checked':''}></label>`).join('')}</div>`,`<button class="button" id="apply-playlist-add">Save selection</button>`);$('#apply-playlist-add').onclick=()=>{p.trackIds=$$('[data-playlist-add]:checked').map(x=>x.dataset.playlistAdd);save();closeModal();render();};break;}
case 'choose-playlist':if(t)choosePlaylist([id]);break;
case 'track-menu':if(t)trackMenu(t);break;
case 'remove-from-playlist':{const p=state.playlists.find(p=>p.id===activePlaylist),old=[...p.trackIds];p.trackIds=p.trackIds.filter(x=>x!==id);save();closeModal();render();toast('Removed from playlist.',()=>{p.trackIds=old;save();render();});break;}
case 'remove-track':{const old=structuredClone({tracks:state.tracks,playlists:state.playlists,queue:state.queue,favorites:state.favorites}),i=state.tracks.findIndex(x=>x.id===id);if(i<0){closeModal();break;}state.tracks.splice(i,1);state.playlists.forEach(p=>p.trackIds=p.trackIds.filter(x=>x!==id));state.queue=state.queue.filter(x=>x!==id);state.favorites=state.favorites.filter(x=>x!==id);if(currentId===id){audio.pause();audio.removeAttribute('src');currentId=null;}state.queueIndex=Math.min(state.queueIndex,Math.max(0,state.queue.length-1));save();closeModal();render();toast('Removed from library. Original file kept.',()=>{Object.assign(state,old);save();render();});break;}
case 'edit-track':if(t){const saved=ensureSaved(t);modal('The details.',`<p class="modal-body-text">Changes affect Velvet’s library only. Original files and service metadata are kept.</p>${['title','artist','album','genre','year'].map(k=>`<label class="modal-field">${k[0].toUpperCase()+k.slice(1)}<input data-metadata="${k}" value="${esc(saved[k]||'')}" maxlength="500"></label>`).join('')}`,`<button class="button" id="save-metadata">Save changes</button>`);$('#save-metadata').onclick=()=>{$$('[data-metadata]').forEach(el=>saved[el.dataset.metadata]=el.dataset.metadata==='year'?Number(el.value)||null:el.value);save();closeModal();render();};}break;
case 'show-file':await api.showInFolder(id);break;
case 'import':importDialog();break;
case 'import-files':{const r=await api.chooseFiles();if(!r.canceled)await importPaths(r.paths);break;}
case 'import-folder':{const r=await api.chooseFolder();if(!r.canceled)await importPaths(r.paths);break;}
case 'cancel-import':closeModal();toast('Import cancelled.');break;
case 'commit-import':await commitImport();break;
case 'preview-link':{const ref=parseServiceLink($('#service-link').value);if(!ref){toast('Use a full supported Spotify, YouTube or SoundCloud share link.');break;}preview=ref;modal('Save this service reference?',`<label class="modal-field">Name<input id="reference-name" value="${esc(ref.title)}" maxlength="500"></label><p class="notice">${esc(ref.source)} · ${esc(ref.type)}<br>${esc(ref.url)}</p><p class="modal-body-text">Saves a link on this computer. Audio, complete metadata and playlist tracks are not downloaded or synchronised.</p>`,`<button class="button secondary" data-action="close-modal">Cancel</button><button class="button" data-action="commit-link">Save reference</button>`);break;}
case 'commit-link':{const ref=preview;if(state.tracks.some(t=>t.externalUrl===ref.url)){toast('This reference is already in your library.');closeModal();break;}state.tracks.push({...ref,title:$('#reference-name').value||ref.title,externalUrl:ref.url,addedAt:new Date().toISOString(),duration:0});save();closeModal();navigate('library');toast('Service reference saved.');break;}
case 'save-reference':if(t){ensureSaved(t);save();closeModal();toast('Saved as a service search reference in your library.');render();}break;
case 'service-search':{const url=getProviderSearchUrl(b.dataset.source,query||'new music');if(url)await api.openExternal(url);break;}
case 'listen-service':if(t){const source=b.dataset.source;await api.openExternal(t.source===source&&t.externalUrl&&!t.externalUrl.includes('/search')?t.externalUrl:getProviderSearchUrl(source,`${t.artist} ${t.title}`));}break;
case 'catalog-search':await searchCatalog();break;
case 'theme':state.settings.theme=b.dataset.value;state.settings.colors={};setTheme();save();render();break;
case 'background-upload':{const result=await api.chooseBackground();if(!result.canceled){state.settings.background=result.background;setTheme();applyBackground();save();render();toast(result.background.type==='video'?'Video background added. It loops silently.':'Background added.');}break;}
case 'clear-background':{const old=state.settings.background;state.settings.background=null;applyBackground();save();if(old?.id)await api.clearBackground(old.id);render();break;}
case 'reset-appearance':for(const key of ['theme','radius','spacing','sidebarWidth','artworkSize','font','dim','blur','compact','queueVisible','reducedMotion'])state.settings[key]=settingsDefaults[key];state.settings.colors={};state.settings.customFont='';setTheme();save();render();break;
case 'export-settings':await flush();await api.exportSettings();break;
case 'import-settings':{const r=await api.importSettings();if(!r.canceled){preview=r.preview;const keys=Object.keys(preview.settings||{});modal('Preview your new setup.',`<p class="modal-body-text">This package replaces the following preferences. Your songs, playlists and history are kept.</p><div class="preview-list">${keys.map(k=>`<div class="preview-item">${esc(k)}</div>`).join('')}</div>`,`<button class="button secondary" data-action="close-modal">Cancel</button><button class="button" data-action="apply-settings-import">Apply setup</button>`);}break;}
case 'apply-settings-import':{applySetup(preview.settings);closeModal();toast('Setup applied.');break;}
case 'export-library':await flush();await api.exportLibrary();break;
case 'import-playlist':{await flush();const r=await api.importPlaylist();if(!r.canceled){preview=r.preview;modal('A collection, ready to come home.',`<p class="modal-body-text">${esc(preview.name)} · ${preview.tracks.length} matched songs</p><div class="preview-list">${preview.tracks.map(t=>`<div class="preview-item">${esc(t.title)}<small>${esc(t.artist)}</small></div>`).join('')}</div><p class="notice">${preview.missing.length} missing or unavailable · ${preview.duplicates.length} duplicates.<br>Local files must already be imported. Unresolved entries are included in the report and will not silently substitute recordings.</p>`,`<button class="button secondary" data-action="close-modal">Cancel</button><button class="button" data-action="commit-playlist-import">Import playlist</button>`);}break;}
case 'commit-playlist-import':{const p={id:uuid(),name:preview.name,description:preview.description||'',trackIds:preview.tracks.map(t=>t.id),createdAt:new Date().toISOString()};for(const t of preview.tracks)if(!state.tracks.some(x=>x.id===t.id))state.tracks.push(t);state.playlists.push(p);save();activePlaylist=p.id;closeModal();navigate('playlist');toast('Playlist imported.');break;}
case 'watch-folder':{await flush();const r=await api.watchFolder();if(!r.canceled){const updated=await api.readState();state.tracks=updated.tracks;state.watchedFolders=updated.watchedFolders;save();render();if(r.preview?.token){preview=r.preview;activeImport=preview.token;modal('Import the songs already here?','<p class="modal-body-text">'+preview.tracks.length+' new songs · '+preview.duplicates.length+' duplicates · '+preview.unavailable.length+' unavailable. Your folder is now watched for future additions.</p><div class="preview-list">'+preview.tracks.slice(0,100).map(t=>'<div class="preview-item">'+esc(t.title)+'</div>').join('')+'</div>','<button class="button secondary" data-action="cancel-import">Skip existing songs</button><button class="button" data-action="commit-import">Import '+preview.tracks.length+' songs</button>');}else toast('Folder is being watched for new music.');}break;}
case 'unwatch':await api.unwatchFolder(id);state.watchedFolders=state.watchedFolders.filter(x=>x.id!==id);render();break;
case 'clear-history':modal('Start a fresh chapter?',`<p class="modal-body-text">Permanently delete ${state.history.length} listening events stored by Velvet. Your songs and playlists will stay.</p>`,`<button class="button secondary" data-action="close-modal">Keep history</button><button class="button danger" data-action="confirm-clear-history">Delete history</button>`);break;
case 'confirm-clear-history':playedSeconds=0;lastPlaybackTime=audio.currentTime;state.history=[];save();closeModal();render();toast('Listening history deleted.');break;
case 'sleep':modal('Let the music tuck you in.',`<p class="modal-body-text">Playback will fade over the last 15 seconds and pause. The timer ends if Velvet is closed.</p><label class="modal-field">Minutes from now<input id="sleep-minutes" type="number" min="1" max="720" value="30"></label>`,`<button class="button secondary" data-action="cancel-sleep">Cancel timer</button><button class="button" data-action="set-sleep">Set timer</button>`);break;
case 'set-sleep':sleepDuration=Math.min(720,Math.max(1,Number($('#sleep-minutes').value)||30))*60000;sleepDeadline=Date.now()+sleepDuration;closeModal();$('#sleep-icon').classList.add('active');toast('Sleep timer set for '+Math.round(sleepDuration/60000)+' minutes.');break;
case 'cancel-sleep':sleepDeadline=0;audio.volume=state.settings.volume;$('#sleep-icon').classList.remove('active');closeModal();toast('Sleep timer cancelled.');break;
case 'command':commandPalette();break;
case 'undo':if(undoAction){undoAction();undoAction=null;$('#toast').classList.remove('show');}break;
case 'close-modal':closeModal();break;
default:if(action?.startsWith('audio-'))lab.handleAction(action,b);break;
}}
function playlistMenu(){const p=state.playlists.find(x=>x.id===activePlaylist);modal(p.name,`<div class="command-list"><button data-action="playlist-rename">Rename & describe</button><button data-action="playlist-duplicate">Duplicate playlist</button><button data-action="playlist-folder">Move into a folder</button>${['json','csv','m3u8'].map(f=>`<button data-action="playlist-export" data-format="${f}">Export ${f.toUpperCase()}</button>`).join('')}<button data-action="playlist-delete">Delete playlist</button></div>`);}
function commandPalette(){modal('Where do you want to go?',`<div class="command-list">${[['discover','Find your frequency'],['library','Your library'],['lab','Audio lab'],['appearance','Customise appearance'],['services','Music services'],['settings','Settings'],['extensions','Extensions']].map(([r,l])=>`<button data-action="navigate" data-route="${r}">${l}<span>→</span></button>`).join('')}<button data-action="import">Import music <kbd>Ctrl O</kbd></button><button data-action="new-playlist">Create a playlist</button><button data-action="smart-playlist">Create a smart playlist</button><button data-action="sleep">Set sleep timer</button></div>`);}
function wireQueueReorder(){$$('[data-queue-index]').forEach(el=>{el.addEventListener('dragstart',e=>{dragIndex=Number(el.dataset.queueIndex);e.dataTransfer.setData('text/velvet-queue',String(dragIndex));});el.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('text/velvet-queue'))e.preventDefault();});el.addEventListener('drop',e=>{if(!e.dataTransfer.types.includes('text/velvet-queue'))return;e.preventDefault();const target=Number(el.dataset.queueIndex),from=Number(e.dataTransfer.getData('text/velvet-queue'));const [id]=state.queue.splice(from,1);state.queue.splice(target,0,id);state.queueIndex=state.queue.indexOf(currentId);save();renderQueue();});});}
function wireReorder(){if(route!=='playlist')return;const p=state.playlists.find(x=>x.id===activePlaylist);if(!p||p.smart)return;$$('[data-track-row][draggable]').forEach(el=>{el.addEventListener('dragstart',e=>e.dataTransfer.setData('text/velvet-playlist',el.dataset.index));el.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('text/velvet-playlist'))e.preventDefault();});el.addEventListener('drop',e=>{if(!e.dataTransfer.types.includes('text/velvet-playlist'))return;e.preventDefault();const from=Number(e.dataTransfer.getData('text/velvet-playlist')),to=Number(el.dataset.index),[id]=p.trackIds.splice(from,1);p.trackIds.splice(to,0,id);save();render();});});}
function normalizePrefs(value={}){const s={...settingsDefaults,...value};for(const [key,min,max] of [['radius',0,30],['spacing',16,48],['sidebarWidth',170,300],['artworkSize',120,230],['dim',0,.96],['blur',0,24],['volume',0,1],['historyRetention',1,365],['breakMinutes',0,720]])s[key]=Math.min(max,Math.max(min,Number(s[key]??settingsDefaults[key]??0)||0));s.theme=THEMES[s.theme]?s.theme:'velvet';s.repeat=['off','all','one'].includes(s.repeat)?s.repeat:'off';s.preferredProvider=['spotify','youtube','soundcloud'].includes(s.preferredProvider)?s.preferredProvider:'youtube';s.colors=Object.fromEntries(Object.entries(s.colors||{}).filter(([k,v])=>['bg','surface','elevated','text','muted','accent','border'].includes(k)&&/^#[\da-f]{6}([\da-f]{2})?$/i.test(v)));for(const key of ['font','customFont'])s[key]=String(s[key]||'').replace(/[^\w -]/g,'').slice(0,60);if(s.background&&(!/^velvet-media:\/\/background\/[a-zA-Z0-9._-]+$/.test(s.background.url)||!['image','video'].includes(s.background.type)))s.background=null;return s;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){e.preventDefault();const action=b.dataset.action;if(action==='playlist-folder'){const p=state.playlists.find(x=>x.id===activePlaylist);modal('Keep things together.',`<label class="modal-field">Folder name<input id="playlist-folder-name" value="${esc(state.folders.find(x=>x.id===p.folderId)?.name||'')}" placeholder="e.g. Late nights"></label><p class="modal-body-text">Use the same name to group playlists. Leave blank to remove the folder.</p>`,`<button class="button" id="apply-playlist-folder">Save</button>`);$('#apply-playlist-folder').onclick=()=>{const name=$('#playlist-folder-name').value.trim();let f=state.folders.find(x=>x.name===name);if(name&&!f){f={id:uuid(),name};state.folders.push(f);}p.folderId=f?.id||'';save();closeModal();render();};return;}Promise.resolve(dispatch(action,b)).catch(err=>{console.error(err);toast(String(err.message||err).replace(/^Error invoking remote method '[^']*': Error: /,''));});}});
$('#search-form').addEventListener('submit',e=>{e.preventDefault();query=$('#global-search').value.trim().slice(0,200);if(route!=='search')navigate('search');searchCatalog();});
let typingTimer;$('#global-search').addEventListener('input',e=>{query=e.target.value.trim().slice(0,200);catalogSequence++;catalog=[];catalogStatus='';clearTimeout(typingTimer);typingTimer=setTimeout(()=>{if(route!=='search')navigate('search');else render();},150);});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.audio){lab.handleInput(el);return;}if(el.id==='volume'){state.settings.volume=Number(el.value)/100;audio.volume=state.settings.volume;audio.muted=false;save();return;}if(el.id==='seek'){if(Number.isFinite(audio.duration))audio.currentTime=Number(el.value)/1000*audio.duration;return;}if(el.dataset.color){state.settings.colors=state.settings.colors||{};state.settings.colors[el.dataset.color]=el.value+(el.dataset.color==='border'?'25':'');setTheme();save();return;}if(el.dataset.setting){const key=el.dataset.setting;if(key==='historyEnabled'){if(state.settings.historyEnabled)recordHistory();playedSeconds=0;lastPlaybackTime=audio.currentTime;}state.settings[key]=el.type==='checkbox'?el.checked:el.type==='range'||['historyRetention','breakMinutes'].includes(key)?Number(el.value):el.value;if(key==='customFont')state.settings.font=el.value||'Segoe UI';setTheme();const out=$(`[data-output="${key}"]`);if(out)out.textContent=el.value+(['radius','spacing','sidebarWidth','artworkSize','blur'].includes(key)?' px':'');if(key==='globalShortcuts')api.setGlobalShortcuts(el.checked).then(r=>{if(r?.failed?.length)toast('Some shortcuts are already in use.');}).catch(e=>toast(e.message));if(key==='visualizer'){engine.applySettings({visualizer:{enabled:el.checked}});state.settings.audio=engine.exportSettings();}save();return;}if(el.id==='library-filter'){const pos=el.selectionStart;state.settings.libraryFilter=el.value;save();render();const input=$('#library-filter');input.focus();input.setSelectionRange(pos,pos);}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.select){el.checked?selectedTracks.add(el.dataset.select):selectedTracks.delete(el.dataset.select);const b=$('[data-action="selection-playlist"]');if(b){b.disabled=!selectedTracks.size;b.textContent=`Add ${selectedTracks.size||''} to playlist`;}return;}if(el.dataset.discovery){filters[el.dataset.discovery]=el.value;render();return;}if(el.id==='library-sort'){state.settings.librarySort=el.value;save();render();}});
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select,[contenteditable="true"]'))return;if(e.target.closest('[data-action]')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.closest('[data-action]').click();return;}if(e.key==='/'&&!e.ctrlKey){e.preventDefault();$('#global-search').focus();}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();commandPalette();}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='o'){e.preventDefault();dispatch('import-files');}else if(e.code==='Space'&&!$('#modal').open){e.preventDefault();togglePlay().catch(e=>toast(e.message));}else if(e.altKey&&e.key==='ArrowRight'){e.preventDefault();nextTrack(1);}else if(e.altKey&&e.key==='ArrowLeft'){e.preventDefault();nextTrack(-1);}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal();});$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
audio.addEventListener('play',()=>{lastPlaybackTime=audio.currentTime;updatePlayer();});audio.addEventListener('pause',()=>{recordHistory();updatePlayer();});audio.addEventListener('loadedmetadata',()=>{$('#duration').textContent=fmt(audio.duration);});
audio.addEventListener('timeupdate',()=>{$('#current-time').textContent=fmt(audio.currentTime);$('#seek').value=Number.isFinite(audio.duration)&&audio.duration>0?Math.round(audio.currentTime/audio.duration*1000):0;const delta=audio.currentTime-lastPlaybackTime;if(!audio.paused&&delta>0&&delta<5){if(state.settings.historyEnabled)playedSeconds+=delta/Math.max(.5,audio.playbackRate);state.settings.listenedSinceBreak=(state.settings.listenedSinceBreak||0)+delta/Math.max(.5,audio.playbackRate);}lastPlaybackTime=audio.currentTime;state.settings.resumePosition=audio.currentTime;if(Date.now()-lastRecord>30000)recordHistory();const breakTime=Number(state.settings.breakMinutes||0)*60;if(breakTime&&state.settings.listenedSinceBreak>=breakTime){state.settings.listenedSinceBreak=0;toast('A little listening break? Rest your ears for a moment.');}});
audio.addEventListener('ended',()=>{if(state.settings.repeat==='one'){audio.currentTime=0;audio.play();}else nextTrack(1);});audio.addEventListener('error',()=>{if(!audio.src)return;toast('This recording is unavailable or its format is unsupported. Reimport the file or use song search to find another recording.');updatePlayer();});
let dragDepth=0;document.addEventListener('dragenter',e=>{if(e.dataTransfer.types.includes('Files')){dragDepth++;$('#drop-overlay').classList.add('active');}});document.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files'))e.preventDefault();});document.addEventListener('dragleave',e=>{if(e.dataTransfer.types.includes('Files')){dragDepth--;if(dragDepth<=0)$('#drop-overlay').classList.remove('active');}});document.addEventListener('drop',e=>{if(!e.dataTransfer.files.length)return;e.preventDefault();dragDepth=0;$('#drop-overlay').classList.remove('active');const paths=[...e.dataTransfer.files].map(f=>api.getPathForFile(f)).filter(Boolean);importPaths(paths).catch(e=>toast(e.message));});
setInterval(()=>{if(sleepDeadline){const remaining=(sleepDeadline-Date.now())/1000;if(remaining<=0){audio.pause();sleepDeadline=0;audio.volume=state.settings.volume;$('#sleep-icon').classList.remove('active');toast('Sleep timer finished. Good night.');}else if(remaining<15)audio.volume=state.settings.volume*(remaining/15);}},500);
document.addEventListener('visibilitychange',()=>{if(backgroundVideo){if(document.hidden)backgroundVideo.pause();else backgroundVideo.play().catch(()=>{});}});
window.addEventListener('beforeunload',()=>{recordHistory();flush();});
api?.onImportProgress(p=>{const el=$('#import-progress');if(el)el.textContent=`Reading ${p.current||p.processed||0} of ${p.total||'?'} files… ${p.fileName||''}`;});
api?.onLibraryChanged(updated=>{state.tracks=updated.tracks;state.watchedFolders=updated.watchedFolders;render();toast('Your watched folder added new music.');});api?.onWatchError(e=>toast(e.message||String(e)));
api?.onMiniMode(value=>document.body.classList.toggle('mini-mode',value));api?.onMediaCommand(c=>{const commands={playPause:'toggle-play',next:'next',previous:'previous',stop:'stop',importFiles:'import-files',importFolder:'import-folder'};if(c==='stop')audio.pause();else dispatch(commands[c]).catch(e=>toast(e.message));});
if('mediaSession'in navigator){for(const [name,handler]of [['play',()=>togglePlay()],['pause',()=>audio.pause()],['nexttrack',()=>nextTrack(1)],['previoustrack',()=>nextTrack(-1)],['seekto',e=>{audio.currentTime=e.seekTime;}]])try{navigator.mediaSession.setActionHandler(name,handler);}catch{}}
async function init(){if(!api){$('#content').innerHTML=empty('Open Velvet on your desktop.','Launch Velvet.exe to use native imports, playback and saved settings. This source page needs the desktop app.');return;}state=await api.readState();state.settings=normalizePrefs(state.settings);engine.applySettings(state.settings.audio||{});state.settings.audio=engine.exportSettings();setTheme();applyBackground();audio.volume=state.settings.volume;for(const [id,name] of [['home-icon','home'],['search-icon','search'],['palette-icon','palette'],['settings-icon','settings'],['shuffle','shuffle'],['repeat','repeat'],['previous-icon','previous'],['next-icon','next'],['lab-icon','lab'],['sleep-icon','sleep'],['volume-icon','volume'],['queue-icon','queue'],['mini-icon','mini']])$('#'+id).innerHTML=icon(name);if(!state.settings.initialized){state.settings.initialized=true;if(localTracks().length){state.queue=localTracks().map(t=>t.id);state.queueIndex=0;if(!state.playlists.length)state.playlists.push({id:'velvet-sessions',name:'Velvet Sessions',description:'Original instrumental sketches. A little music to make yourself at home.',trackIds:localTracks().map(t=>t.id),createdAt:new Date().toISOString()});}}currentId=state.queue[state.queueIndex]||null;const t=current();if(t?.source==='local'){audio.src=t.mediaUrl;historyTrack=t.id;const pos=Number(state.settings.resumePosition)||0;audio.addEventListener('loadedmetadata',()=>{if(pos<audio.duration)audio.currentTime=pos;},{once:true});}if(state.recovery)toast(state.recovery);const cutoff=Date.now()-state.settings.historyRetention*86400000;state.history=state.history.filter(e=>Date.parse(e.at)>cutoff);save();render();document.body.dataset.ready='true';}
init().catch(e=>{$('#content').innerHTML=empty('We could not open your library.',e.message);console.error(e);});

export function applySetup(preferences){state.settings=normalizePrefs({...state.settings,...preferences});engine.applySettings(state.settings.audio||{});state.settings.audio=engine.exportSettings();setTheme();applyBackground();audio.volume=state.settings.volume;save();render();}

export async function prepareToClose(){audio.pause();recordHistory();await flush();}
